 if(![rows isKindOfClass:NSArray.class])return NO;
 for(NSDictionary *fresh in rows){
  if([fresh[@"url"] isEqual:wanted])return YES;
  for(NSDictionary *source in fresh[@"sources"])if([source[@"url"] isEqual:wanted])return YES;
 }
