@property(nonatomic,strong)NSCache *thumbs;
@property(nonatomic,strong)NSMutableSet *loading;
@property(nonatomic,strong)NSMutableArray *thumbJobs;
@property(nonatomic,strong)NSMutableSet *selectedURLs;
@property(nonatomic,strong)NSMutableSet *submitting;
@property(nonatomic,strong)NSTimer *timer;
@property(nonatomic,strong)UIBarButtonItem *downloadButton;
@end
@implementation PVXImageGallery
- (void)viewDidLoad{[super viewDidLoad];self.title=@"图片下载";self.rows=@[];self.tasks=@[];self.cookies=nil;self.ua=@"";self.thumbs=[NSCache new];self.thumbs.countLimit=80;self.loading=[NSMutableSet set];self.thumbJobs=[NSMutableArray array];self.selectedURLs=[NSMutableSet set];self.submitting=[NSMutableSet set];self.tableView.rowHeight=84;self.tableView.allowsMultipleSelection=YES;self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemDone target:self action:@selector(close)];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemRefresh target:self action:@selector(refresh)];self.downloadButton=[[UIBarButtonItem alloc] initWithTitle:@"下载选中" style:UIBarButtonItemStyleDone target:self action:@selector(downloadSelected)];self.toolbarItems=@[[[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],self.downloadButton];self.navigationController.toolbarHidden=NO;[[NSNotificationCenter defaultCenter] addObserver:self selector:@selector(mediaChanged:) name:@"PVXMediaChanged" object:nil];WKWebView *w=PVXCollectionWebView();[w.configuration.websiteDataStore.httpCookieStore getAllCookies:^(NSArray *cookies){self.cookies=cookies;[self.tableView reloadData];}];[w evaluateJavaScript:@"navigator.userAgent" completionHandler:^(id v,NSError *e){if([v isKindOfClass:NSString.class])self.ua=v;}];[self refresh];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];__weak typeof(self)weak=self;self.timer=[NSTimer scheduledTimerWithTimeInterval:2 repeats:YES block:^(NSTimer *t){[weak reloadTasks];}];[self reloadTasks];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[self.timer invalidate];self.timer=nil;}
- (void)dealloc{[[NSNotificationCenter defaultCenter] removeObserver:self];[_timer invalidate];for(PVXThumbnail *j in _thumbJobs)[j.session invalidateAndCancel];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (void)refresh{[[PVXMediaBridge shared] refresh];self.rows=[[PVXMediaBridge shared] images];[self.tableView reloadData];[self updateButton];}
- (void)mediaChanged:(NSNotification*)n{if(n.object!=PVXCollectionWebView())return;self.rows=[[PVXMediaBridge shared] images];[self.tableView reloadData];[self updateButton];}
- (void)updateButton{self.title=[NSString stringWithFormat:@"图片 · %lu",(unsigned long)self.rows.count];self.downloadButton.title=[NSString stringWithFormat:@"下载选中 (%lu)",(unsigned long)self.selectedURLs.count];self.downloadButton.enabled=self.selectedURLs.count>0;}
- (void)reloadTasks{NSString *dir=[PVXStateRoot() stringByAppendingPathComponent:@"image-tasks"];dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSMutableArray *rows=[NSMutableArray array];NSArray *names=[NSFileManager.defaultManager contentsOfDirectoryAtPath:dir error:nil];for(NSString *name in names){if(![name.pathExtension isEqual:@"plist"]||![[NSUUID alloc] initWithUUIDString:name.stringByDeletingPathExtension])continue;NSString *path=[dir stringByAppendingPathComponent:name];NSDictionary *attrs=[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil];if([attrs[NSFileSize] unsignedLongLongValue]>12*1024*1024)continue;NSDictionary *v=[NSDictionary dictionaryWithContentsOfFile:path];if([v isKindOfClass:NSDictionary.class])[rows addObject:v];if(rows.count>=500)break;}[rows sortUsingComparator:^NSComparisonResult(id a,id b){return [b[@"created"] compare:a[@"created"]];}];dispatch_async(dispatch_get_main_queue(),^{self.tasks=rows;[self.tableView reloadSections:[NSIndexSet indexSetWithIndex:1] withRowAnimation:UITableViewRowAnimationNone];});});}
- (NSInteger)numberOfSectionsInTableView:(UITableView*)table{return 2;}
- (NSInteger)tableView:(UITableView*)table numberOfRowsInSection:(NSInteger)section{return section==0?self.rows.count:self.tasks.count;}
- (NSString*)tableView:(UITableView*)table titleForHeaderInSection:(NSInteger)section{return section==0?@"当前网页图片 · 点选后下载原文件":@"图片下载任务";}
- (NSString*)tableView:(UITableView*)table titleForFooterInSection:(NSInteger)section{return section==0?@"支持当前页面及 iframe、已创建的开放 Shadow DOM 中的图片。小于 48×48 的已知小图已过滤；点击刷新可检测新加载图片。下载保留服务器提供的图片原始格式。":@"队列由独立后台服务执行，关闭此面板后继续下载。图片与原视频任务分开管理。";}
- (UITableViewCell*)tableView:(UITableView*)table cellForRowAtIndexPath:(NSIndexPath*)path{UITableViewCell *cell=[table dequeueReusableCellWithIdentifier:@"image"];if(!cell)cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"image"];cell.textLabel.numberOfLines=1;cell.detailTextLabel.numberOfLines=2;cell.imageView.image=[UIImage systemImageNamed:path.section==0?@"photo":@"arrow.down.circle"];cell.imageView.contentMode=UIViewContentModeScaleAspectFit;cell.accessoryType=UITableViewCellAccessoryNone;NSDictionary *row=path.section==0?self.rows[path.row]:self.tasks[path.row];cell.textLabel.text=PVXString(row[@"title"],180)?row[@"title"]:@"图片";NSString *url=row[@"url"];if(path.section==0){cell.detailTextLabel.text=[NSString stringWithFormat:@"%@ × %@ · %@",row[@"width"],row[@"height"],[NSURL URLWithString:url].host?:@""];cell.accessoryType=[self.selectedURLs containsObject:url]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;UIImage *cached=[self.thumbs objectForKey:url];if(cached){cell.imageView.image=cached;}else if(self.cookies&&self.thumbJobs.count<3&&![self.loading containsObject:url]){[self.loading addObject:url];__weak typeof(self)weak=self;__block __weak PVXThumbnail *weakJob;PVXThumbnail *job=[[PVXThumbnail alloc] initWithURL:PVXImageURL(url) cookies:self.cookies referer:row[@"page"]?:@"" ua:self.ua?:@"" done:^(UIImage *image){typeof(self)self=weak;if(!self)return;if(image)[self.thumbs setObject:image forKey:url];[self.thumbJobs removeObject:weakJob];[self.tableView reloadData];}];weakJob=job;[self.thumbJobs addObject:job];}}else{NSDictionary *states=@{@"queued":@"等待下载",@"downloading":@"下载中",@"ready":@"下载成功 · 可保存到文件",@"saving":@"保存相册中",@"saved":@"已保存相册",@"failed":@"失败",@"uncertain":@"相册结果待确认"};NSString *state=states[row[@"state"]]?:row[@"state"]?:@"";NSString *error=PVXString(row[@"error"],2000)?row[@"error"]:@"";cell.detailTextLabel.text=error.length?[NSString stringWithFormat:@"%@ · %@",state,error]:state;if([row[@"state"] isEqual:@"saved"])cell.accessoryType=UITableViewCellAccessoryCheckmark;}return cell;}
- (void)tableView:(UITableView*)table didSelectRowAtIndexPath:(NSIndexPath*)path{[table deselectRowAtIndexPath:path animated:YES];if(path.section!=0){NSMutableDictionary *t=[self.tasks[path.row] mutableCopy];t[@"kind"]=@"image";UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"图片任务" message:PVXString(t[@"error"],2000)?t[@"error"]:nil preferredStyle:UIAlertControllerStyleActionSheet];if(PVXTaskHasLocalFile(t)){[menu addAction:[UIAlertAction actionWithTitle:@"保存到文件" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){PVXExportTaskToFiles(t);}]];if([t[@"state"] isEqual:@"ready"]||[t[@"state"] isEqual:@"failed"])[menu addAction:[UIAlertAction actionWithTitle:@"保存到相册" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){PVXSaveTaskToPhotos(t);}]];}[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.sourceView=table;menu.popoverPresentationController.sourceRect=[table rectForRowAtIndexPath:path];[self presentViewController:menu animated:YES completion:nil];return;}NSString *url=self.rows[path.row][@"url"];if([self.selectedURLs containsObject:url])[self.selectedURLs removeObject:url];else[self.selectedURLs addObject:url];[table reloadRowsAtIndexPaths:@[path] withRowAnimation:UITableViewRowAnimationNone];[self updateButton];}
- (void)downloadSelected{NSArray *selected=[self.rows filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *r,NSDictionary *bindings){return [self.selectedURLs containsObject:r[@"url"]]&&![self.submitting containsObject:r[@"key"]];}]];for(NSDictionary *row in selected){NSString *key=row[@"key"];[self.submitting addObject:key];PVXSubmitMedia(row,^(NSDictionary *receipt,NSString *error){[self.submitting removeObject:key];if(receipt)[self.selectedURLs removeObject:row[@"url"]];[self updateButton];[self.tableView reloadData];if(error)PVXAlert(@"圖片任務提交失敗",error);});}return;}
@end
void PVXShowImages(void){dispatch_async(dispatch_get_main_queue(),^{UIViewController *p=PVXPresenter();if(!p)return;if([p isKindOfClass:PVXImageGallery.class])return;PVXImageGallery *g=[PVXImageGallery new];UINavigationController *nav=[[UINavigationController alloc] initWithRootViewController:g];nav.modalPresentationStyle=UIModalPresentationPageSheet;if(@available(iOS 15.0,*)){nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.largeDetent];nav.sheetPresentationController.prefersGrabberVisible=YES;}[p presentViewController:nav animated:YES completion:nil];});}
static void(*PVXOrigPrepare)(id,SEL,id),(*PVXOrigTrack)(id,SEL,id),(*PVXOrigPanelLoad)(id,SEL);
static void PVXPrepare(id self,SEL cmd,id config){PVXOrigPrepare(self,cmd,config);[[PVXMediaBridge shared] configure:config];}
static void PVXTrack(id self,SEL cmd,id web){PVXOrigTrack(self,cmd,web);if([web isKindOfClass:WKWebView.class])[[PVXMediaBridge shared] configure:((WKWebView*)web).configuration];}
static void PVXPanelLoad(id self,SEL cmd){PVXOrigPanelLoad(self,cmd);UITableView *table=PVXGet(self,@"table");if(![table isKindOfClass:UITableView.class]||objc_getAssociatedObject(table,&PVXGalleryKey))return;UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem];button.frame=CGRectMake(0,0,table.bounds.size.width,46);button.autoresizingMask=UIViewAutoresizingFlexibleWidth;[button setTitle:@"  检测并下载网页图片" forState:UIControlStateNormal];[button setImage:[UIImage systemImageNamed:@"photo.on.rectangle.angled"] forState:UIControlStateNormal];[button addAction:[UIAction actionWithHandler:^(__kindof UIAction *action){PVXShowImages();}] forControlEvents:UIControlEventTouchUpInside];table.tableHeaderView=button;objc_setAssociatedObject(table,&PVXGalleryKey,button,OBJC_ASSOCIATION_RETAIN_NONATOMIC);}
static BOOL PVXTypeMethod(Class c,SEL s,unsigned count){Method m=class_getInstanceMethod(c,s);if(!m||method_getNumberOfArguments(m)!=count)return NO;char *ret=method_copyReturnType(m);BOOL ok=ret&&ret[0]=='v';free(ret);if(count>2){char *arg=method_copyArgumentType(m,2);ok=ok&&arg&&arg[0]=='@';free(arg);}return ok;}
void PVXInstallImages(void){Class c=NSClassFromString(@"PVBrowser"),p=NSClassFromString(@"PVPanel");SEL prepare=NSSelectorFromString(@"prepareConfiguration:"),track=NSSelectorFromString(@"track:"),load=@selector(viewDidLoad);if(PVXTypeMethod(c,prepare,3))PVXHook(c,prepare,(IMP)PVXPrepare,(IMP*)&PVXOrigPrepare);if(PVXTypeMethod(c,track,3))PVXHook(c,track,(IMP)PVXTrack,(IMP*)&PVXOrigTrack);if(PVXTypeMethod(p,load,2))PVXHook(p,load,(IMP)PVXPanelLoad,(IMP*)&PVXOrigPanelLoad);id panel=PVXGet(PVXBrowser(),@"panel");if([panel isKindOfClass:UIViewController.class]&&[panel isViewLoaded]){UITableView *t=PVXGet(panel,@"table");if(t&&!objc_getAssociatedObject(t,&PVXGalleryKey))PVXLog(@"existing panel will acquire image entry after Safari restart");}WKWebView *w=PVXCollectionWebView();if(w){[[PVXMediaBridge shared] configure:w.configuration];[[PVXMediaBridge shared] refresh];}}
